type User {
  id: ID!
  name: String!
  email: String! @requiresAuth
  posts(first: Int = 10): [Post!]!
}

type Post {
  id: ID!
  title: String!
  author: User!
}

type Query {
  user(id: ID!): User
}

type Mutation {
  updateEmail(userId: ID!, email: String!): User!
}

# Client asks for exactly this shape. Nothing more is sent.
query GetUser {
  user(id: "7") {
    name
    posts(first: 5) {
      title
    }
  }
}
# Response mirrors the selection tree, field for field.

const server = new ApolloServer({
  schema,
  validationRules: [
    depthLimit(6), // reject deeply nested selections
    costLimit({ maxCost: 1000, // price list args: first:10 = 10 points
      scalarsCost: 1, objectCost: 5 })
  ],
  plugins: [
    persistedQueries({ allowlist: true }), // only shipped hashes execute
    responseCache({ scopePerField: true }), // cache User:7, not the query string
  ],
});
// Resolvers must batch: one IN-query per tick, auth per field.
const loaders = () => ({
  postsByUser: new DataLoader((ids) => batchPosts(ids))
});
